-- T-114: a cover photo for every lesson, hosted on the project's Cloudinary (folder cryptopilot/academy) and
-- delivered cropped to 16:9. The photos come from Unsplash under the Unsplash License; cover_credit names the
-- photographer, shown under the cover.
ALTER TABLE academy_article ADD COLUMN cover_image_url varchar(500);
ALTER TABLE academy_article ADD COLUMN cover_credit varchar(200);

